import{_ as e,o as l,c as i,a6 as p}from"./chunks/framework.B_q3ZJNF.js";const u=JSON.parse('{"title":"行为陷阱：为什么聪明人也亏钱","description":"","frontmatter":{"title":"行为陷阱：为什么聪明人也亏钱"},"headers":[],"relativePath":"astock-course/12-behavior-traps.md","filePath":"astock-course/docs/12-behavior-traps.md"}'),r={name:"astock-course/12-behavior-traps.md"};function t(o,a,s,h,d,n){return l(),i("div",null,[...a[0]||(a[0]=[p('<h1 id="行为陷阱-为什么聪明人也亏钱" tabindex="-1">行为陷阱：为什么聪明人也亏钱 <a class="header-anchor" href="#行为陷阱-为什么聪明人也亏钱" aria-label="Permalink to &quot;行为陷阱：为什么聪明人也亏钱&quot;">​</a></h1><p>2021 年 1 月，基金销售圈出现一种久违的场面：抢的不是房，不是车，是当天才开始发售的新基金。多只新基金开售当天即告售罄，单只认购资金冲到千亿级，热门到需要按比例配售——认购的钱太多，只能按比例确认其中一部分（公开报道口径，2021 年 1 月）。「爆款基金」这个词就在那个月刷屏；饭桌上，从不谈股票的亲戚开始晒基金收益，开户预约排起了队。这场抢购里没有骗子，没有假消息，产品也合规，每一环单看都正常。</p><p>三年后回头看，抢在最热闹处进场的人，大多还套在水下：此后权益基金净值普遍大幅回调（公开报道口径，定性表述）。值得追问的恰恰在这里：这群人里不缺聪明人，不缺勤奋人，信息也不算少——聪明、勤奋、消息灵通，为什么没能拦住那笔亏损？</p><p>这一章不新增任何公式，只拆四个心理机关——它们如何劫持一次完全正常的决策；以及比识别更要紧的：每一条机械防御规则怎么写、怎么判定自己守没守住。全章故事与账目均为教学合成示意；公开事件采用公开报道口径并标注时间；行为金融实验的表述取文献定性结论。本章不构成任何投资建议。</p><h2 id="工具箱" tabindex="-1">工具箱 <a class="header-anchor" href="#工具箱" aria-label="Permalink to &quot;工具箱&quot;">​</a></h2><p>本章调用四块旧积木，全部改当防御工事用。盈亏不对称——亏损与回本所需涨幅在百分比上不对称，亏 30% 要涨约 43% 才回本，亏得越深翻身越贵（第 9 章）；最大回撤——从历史最高点到其后最低点的最大跌幅，量最惨的一段（第 9 章）；仓位管理——按风险预算决定每笔金额的规则体系：单笔可亏额 = 总资金 × 单笔风险预算，再由（买入价 − 止损价）反推可买数量（第 11 章）；再平衡——组合比例偏离目标后，卖出超配、买入低配，机械地拨回原位（第 10 章）。四块旧的各就各位：两块当测量仪（盈亏不对称给「扛」定价，最大回撤给最惨那段记账），两块当骨架（仓位管理与再平衡，本章给它们配上防情绪的岗位）。</p><h2 id="原理-陷阱不考智力-考的是谁在扣扳机" tabindex="-1">原理：陷阱不考智力，考的是谁在扣扳机 <a class="header-anchor" href="#原理-陷阱不考智力-考的是谁在扣扳机" aria-label="Permalink to &quot;原理：陷阱不考智力，考的是谁在扣扳机&quot;">​</a></h2><p>先替「怪自己笨」这个直觉说句公道话：交易表面上就是一场信息与智力的比赛——谁研究得深、谁动作快，谁就赢；亏了钱先怀疑自己笨、怪消息不灵，方向感没有错。它恰好失效的边界在于：把人带进坑里的那一步，往往发生在智力和信息上岗之前。心理学把心智的运转拆成两套方式（此处沿用行为心理学的通行叫法）：系统一——快、自动、不费力，靠直觉与情绪直达答案；系统二——慢、刻意、费力气，负责推理与自我控制。替你接电话、躲开水坑、一眼认出老朋友的是系统一；做年度预算、逐行核对账单的是系统二。交易里的每一步名义上都归系统二管，真正扣扳机的却常常是系统一：它快出一大截——等系统二赶到，单子早就挂出去了。</p><p>所以「亏钱是因为不够聪明或信息不够」这句话站不住。它的隐含假设是陷阱设在智力与信息的赛道上，事实上几类陷阱全都不设在那里——本章会反复看到同一个图案：决定动作的不是想得对不对，是情绪抢在思考之前按下了按钮。这不是推断，是有公开样本的事实。对职业投资者持仓的实证研究，观察到了与普通投资者同款的行为偏差（行为金融文献口径，稍后展开）；三百年来流传最广的投资轶事，主角恰恰是写过《自然哲学的数学原理》的那颗头脑——据轶事口径，牛顿在南海泡沫（18 世纪 20 年代英国那场著名的股市狂热与崩盘）中先获利离场；又在身边人的热络裹挟下于更高位重新入场，最后亏掉一大笔财产。轶事细节无从精确考证，可它流传三百年这件事本身就在说话：聪明人中招，从来不稀奇。</p><h3 id="损失厌恶-亏的疼-约为赚的乐的两倍" tabindex="-1">损失厌恶：亏的疼，约为赚的乐的两倍 <a class="header-anchor" href="#损失厌恶-亏的疼-约为赚的乐的两倍" aria-label="Permalink to &quot;损失厌恶：亏的疼，约为赚的乐的两倍&quot;">​</a></h3><p>损失厌恶——同额亏损带来的痛苦，约为同额盈利带来的快乐的两倍（行为金融文献的经典实验口径：卡尼曼与特沃斯基在一系列决策实验中反复测得这个不对称；文献常把系数粗略记作 2）。真实感场景人人可复现：同一周里，一笔资金变动让你的账户多了 3000 元，另一笔少了 3000 元，净额为零，心情却不是零——哪一笔更占心思？实验与日常经验给出同一个答案：亏的那笔，而且占的不止一点。</p><p>反事实检验这个不对称有多要紧：假如亏损与盈利同等疼乐，一道「一半机会赢一点、一半机会输一点、数学期望为正」的赌局应当无人拒绝；实验室里反复出现的画面恰恰相反——多数参与者拒绝了它（同一文献口径）。赢的那点快乐，抵不过输的那点疼，疼在决策里占了双倍权重。</p><p>这份疼还有生理的一面。神经经济学的脑成像研究观察到，亏损信号触发的身心反应模式与应对威胁的反应相似（文献口径，此处只取定性结论）。疼是生理事件，不是性格缺陷，也不随聪明程度打折——这就顺手拆掉了第二个流传很广的说法：「拿得住靠的是意志力」。意志力是系统二的预算，慢、易疲劳，而情绪最凶的时刻恰好是它最弱的时刻；指望用它压住系统一的威胁反应，等于让最慢的部门去堵最快的枪。**拿得住不靠忍，靠提前把疼标价：亏损在进场前就有了上限，疼落在预算之内，认错就退化成执行一条写好的规则。**工具就是仓位管理（第 11 章）——先定「这笔最多输多少」，再用止损价反推数量。</p><p>防御规则（机械版）：无止损不下单。任何一笔买入之前，先写下两个数——止损价与单笔可亏额（总资金 × 单笔风险预算，第 11 章）；可亏额 ÷（买入价 − 止损价）就是可买数量。判定标准：翻出持仓清单，每一笔后面都附有这两个数——有或没有，一眼可判；没有，就不许开新仓。</p><h3 id="处置效应-按成本价决策-而不是按公司" tabindex="-1">处置效应：按成本价决策，而不是按公司 <a class="header-anchor" href="#处置效应-按成本价决策-而不是按公司" aria-label="Permalink to &quot;处置效应：按成本价决策，而不是按公司&quot;">​</a></h3><p>处置效应——盈利的持仓急着卖、亏损的持仓不肯卖的倾向，行话叫卖盈持亏。这个名字由谢弗林与斯塔特曼在 1985 年的行为金融文献中给出；此后对真实交易记录的实证研究反复观察到同一幅画面：卖出盈利持仓的倾向，明显高于卖出亏损持仓（文献口径）。真实感场景：急用钱，必须卖掉两只中的一只——甲票浮盈 15%，乙票浮亏 25%。多数人不假思索卖甲留乙，理由顺手就来：「落袋为安」「乙还没回本」。一周后甲票又涨一截，乙票继续下探，「卖了就涨」的懊恼清单上又添一行。还有人拿手续费当留下的理由——算一下就知道站不住：一万元市值的卖出，佣金、印花税、过户费（第 3 章）加总约 10 元，千分之一的量级；拿 10 元的过路费当理由，守的却是一扇通往 30% 深坑的门。</p><p>成因要看清一个空位：决策席上坐着成本价。成本是沉没的历史——它记在你与券商的交割单上，不属于这家公司的未来。可处置效应里，成本价坐上了决策席：卖出乙票，等于把「账面亏损」盖成「真实亏损」，疼从「可能」落实为「必然」；不卖，就还能对自己说「没亏，只是还没涨回来」。反过来，卖出甲票是把快乐落袋，顺带锁死了「得而复失」的可能。一疼一乐，系统一替你选完了。可验证的后果：如果成本价真是无关变量，去留决策就应当与浮盈浮亏无关；实证观察到的强相关，恰好暴露决策参照的不是公司，是成本。</p><p>「那是普通投资者的毛病」——这句辩解同样站不住。对职业投资者持仓的大样本研究也观察到处置效应（行为金融文献口径）；职业训练升级的是系统二，劫持决策时机的仍是系统一。机构真正的优势是把防御工程化——预算、清单、日历，这正是普通投资者最该抄的作业。</p><p>防御规则（机械版）：季度去留日。固定一个日历日（比如每季度第一个周末），对每只持仓回答一个二选一问题——这只票，按今天的基本面还留吗？判定材料与成本价无关，全是价值一侧的家底与尺子：三张表（资产负债表、利润表、现金流量表，第 6 章）查真赚钱没有；五项体检指标（毛利率、净利润、应收账款、货币资金、经营现金流，第 6 章）查赚得实不实、钱收回来没有；四把估值尺（市盈率、盈利收益率、市净率、股息率，第 7 章）对照无风险利率（第 7 章）查贵不贵；能力圈与护城河（第 8 章）查资格与保质期。答案只有「留」或「卖」，当天写进持仓清单，一季后可复核。判定标准：清单上每只票都有当季留痕——有或没有，一眼可判。</p><h3 id="锚定效应-分母错了-贵贱跟着错" tabindex="-1">锚定效应：分母错了，贵贱跟着错 <a class="header-anchor" href="#锚定效应-分母错了-贵贱跟着错" aria-label="Permalink to &quot;锚定效应：分母错了，贵贱跟着错&quot;">​</a></h3><p>锚定效应——把与价值无关的数字当成决策的参照点，最常见的两只「锚」是自己的成本价与历史最高价。锚是船只定位用的重物；判断一旦拴在错的数字上，后面每一步推理都跟着偏。真实感场景：同一只票、同一个收盘日，12 元买入的人看着 8 元的现价喊「跌了三分之一，太便宜了，补仓」；20 元买入的人看着同一个 8 元喊「跌了六成，这票完蛋了」。公司没变，价格没变，两个「合理」结论打架——因为两人的分母都不是这家公司，是各自的成本。</p><p>「贵」与「便宜」永远相对某个分母成立，锚定效应的全部错误就在分母上。合法的分母只有价值一侧：内在价值区间与安全边际（第 8 章），或盈利收益率对照无风险利率（第 7 章）。成本价、历史最高价、基金净值的前期高点，都只是你账户里的历史坐标，与公司值多少无关。反事实检验：成本价若真是「合理价」，同一只票就该一人一个「合理价」，而价值只有一个。2021 年 1 月的抢购还提供了第二个公开样本：基金销售页上最醒目的是那条向上爬的复利曲线（第 1 章）——把「过去两年涨了多少」当分母去推断「未来也会」，正是把锚抛在了行情的顶部。</p><p>防御规则（机械版）：分母规则。任何「太贵了 / 太便宜了」的判断，必须当场写明分母——相对什么？分母只能出自价值一侧（估值尺第 7 章、价值区间第 8 章）；成本价、历史最高价、净值新高均不合法。随身再配一个自查，就是那个空仓之问：假如今天空仓，我还会按现价买它吗？判定标准：每一条买卖理由旁边都指得出一处分母——指不出，判断作废。</p><h3 id="从众效应-拥挤本身会造出顶部" tabindex="-1">从众效应：拥挤本身会造出顶部 <a class="header-anchor" href="#从众效应-拥挤本身会造出顶部" aria-label="Permalink to &quot;从众效应：拥挤本身会造出顶部&quot;">​</a></h3><p>从众效应——跟随大多数人行动的倾向：别人买我也买，别人跑我也跑。真实感场景不必远求，开篇那场抢购就是标准样本：从不谈股票的亲戚开始晒收益，茶水间话题从房价换成了基金代码，开户预约排起了队。整条链上没有任何环节要求你独立判断，每个环节都在替你出示同一句话——「别人已经判断过了」。</p><p>机制在拥挤本身。价格由增量资金推着走：愿意出更高价的新买家不断进场，价格才不断抬升；而从众恰恰是增量资金最猛的阶段。于是最热闹处买入的人，买的其实不是价格，是「还有下一个人」的假设——能被调动的钱都进场之后，接棒的还有谁？**最贵的价格与最挤的人群，是同一时刻的两面。**人群的判断力止步于把价格推贵：如果人群总在便宜处进场，「抢在最热闹处」就不会是反复上演的剧情。开篇的公开样本再次对上：抢购潮与随后三年权益基金的普遍大幅回调先后出现（公开报道口径）。</p><p>防御规则（机械版）：拥挤警报 + 日历再平衡。警报词表贴在交易软件旁边——从不谈股的人开始荐股、开户要排队、亲友群晒单成风——任一出现，只登记、不新增主动买入；已有组合照旧按固定日历执行再平衡（第 10 章）：超配的卖一点、低配的买一点，让卖高买低由日历触发，不由人群触发。判定标准：警报期内新增主动买入笔数为零、再平衡有日期与比例记录——翻开记录，有或没有，一眼可判。</p><h3 id="组装-把决策权移交给规则" tabindex="-1">组装：把决策权移交给规则 <a class="header-anchor" href="#组装-把决策权移交给规则" aria-label="Permalink to &quot;组装：把决策权移交给规则&quot;">​</a></h3><p>四条规则合起来是一次组装。**机械防御 = 仓位管理（第 11 章，管「最多输多少」）+ 再平衡（第 10 章，管「卖高买低」）+ 去留日与分母规则（本章，管「去留」与「贵贱」）⇒ 把决策权从扣扳机那一刻的情绪手里，移交给进场之前冷静的自己。**四条规则的共同点只有一个：全部在事前写成可判定的形式——写死的数字、固定的日期、二选一的问题；到了执行时刻，反而最不需要智力，也不需要意志力。这就是本章的总纲：防御靠规则，不靠意志力——意志力是对抗系统一的自欺，规则才是绕开它的路。</p><h2 id="案例推演-老周的一年-与一次重放" tabindex="-1">案例推演：老周的一年，与一次重放 <a class="header-anchor" href="#案例推演-老周的一年-与一次重放" aria-label="Permalink to &quot;案例推演：老周的一年，与一次重放&quot;">​</a></h2><p>口径先立好：人物与账户均为教学合成，每一笔数字都是示意；行情背景取公开报道口径的 2021 年市场环境，与任何真实账户、真实个人无关。看这份示意账本不为给谁定罪，为的是把陷阱的连锁过程放到放大镜底下。</p><p>老周的一年（示意）。1 月，表哥在家庭群里晒基金收益，老周申购了 6 万元爆款基金，顺手开了股票账户。2 月，基金净值冲高，账户浮盈约三成（示意），群里更热了。他决定自己下场买股票，自学起技术分析：K线——一根蜡烛记下开高低收（第 4 章）；阳线与阴线看当日多空、上影线与下影线记一度冲到却没守住的高与低（第 4 章）；放量（成交量——价格运动的燃料，第 4 章）当确认；均线与趋势（第 5 章）定方向，金叉与死叉（第 5 章）当买入按钮，支撑与压力（第 5 章）画好进出地带。工具不可谓不齐全。</p><p>5 月，一只板块票（也叫它乙票，与上文处置效应场景里的乙票无关）出现金叉又放量，老周在开盘集合竞价（第 3 章）里挂高价追入 2 万元，成本 8.00 元。买入当天他想先落袋一次小冲高，T+1（第 3 章）不允许——当天买的，次一交易日才能卖。一周后乙票涨到 9.20 元，浮盈 15%，他全卖了：「到手的利润不能飞。」两周后乙票站上 10 元。7 月，他又追进一只更热的丙票，成本 12.00 元；随后板块退潮，丙票跌到 8.40 元，浮亏 30%，其间一个交易日还被封在一字跌停的涨跌停板上（第 3 章）——想卖，卖单堆着轮不到他。「回到 12 我就走」，这句话他说了半年。</p><p>12 月盘点，收益率的尺子（第 1 章）量出全年为负（示意）。他没算过的账有好几笔：丙票亏 30%，回本涨幅（第 9 章）要约 43%——盈亏不对称（第 9 章）在他账户里现了形；最大回撤（第 9 章）从没量过，波动率（第 9 章）量的是日常颠簸，真正压垮他的是最深那一段；每天盯盘的四个小时，盯的全是情绪的刻度。三年后：基金仍套在水下（示意，公开口径下的普遍情形）；丙票的报表上，应收账款增速远超营收、经营现金流长期低于净利润（第 6 章的两条红旗）——这些他一次都没翻过；货币资金与有息负债的对照（第 6 章）、毛利率的变化（第 6 章），同样无人过问。</p><p>他买的东西他没看过一眼：基金与股票背后都是公司股权（第 2 章），长期回报长在盈利与估值两个因子上（第 2 章），市值 = 盈利 × 估值倍数（第 2 章）；而 2021 年初的拥挤价格里，贵的主要是估值那一半。判词随之而来：老周不缺工具，缺一张提前写好的单子。他的每一步单看都「合理」——落袋为安、等回本、跟着大家买——四个陷阱一路连锁：从众把他带进场，锚定给他一个假分母，损失厌恶让他不敢认错，处置效应最后把账户修剪成「满手浮亏仓」。四种陷阱很少单独出场，它们是彼此的开路人。还有一层他没算的账：名义回本不等于真实回本——等待本身有代价（货币时间价值，第 1 章），物价还在每年抬脚（通货膨胀，第 1 章）；就算净值回到申购价，实际购买力（第 1 章）也已经缩水。而他的 10 万元从头到尾押在同一个方向上——分散化（第 10 章）与资产配置（第 10 章）从没进场，基金与两只热点票的相关性（第 10 章）高得像同一只票。</p><p>重放（示意）。同一段行情再来一遍，老周只改四步，一步都不多花钱。第一，1 月进场前先写预算：这笔钱最多亏多少（仓位管理，第 11 章），警报词表贴在软件旁边。第二，5 月乙票同样买入、同样 +15%，季度去留日给出「留」——基本面没变，不因浮盈卖出；注意，「留」是判定出来的，不是扛出来的，若判定是「不买」，同样的浮盈也该落袋。第三，丙票买入当天止损价一并写进持仓单，跌破当日收盘、次日开盘执行——离场时浮亏约 9%（示意），回本涨幅约 10%（第 9 章）：坑浅一截，翻身便宜一截。第四，每半年把组合拨回目标比例（再平衡，第 10 章），卖超配、买低配。重放账户的全年收益率同样为负（示意）——系统性回调谁都躲不开（第 10 章）——但每一步有记录、可复核：预算单、去留留痕、止损价、再平衡日期。差别不在哪一年赚得多，在下一轮行情来的时候，谁手里还有完整的仓位与完整的判断力。</p><h2 id="解释检查-四段操作-先判后对" tabindex="-1">解释检查：四段操作，先判后对 <a class="header-anchor" href="#解释检查-四段操作-先判后对" aria-label="Permalink to &quot;解释检查：四段操作，先判后对&quot;">​</a></h2><p>第一件事，复述。合上书，向一位没碰过股票的家人说清一句话：为什么「拿得住」不能指望意志力？对照两个判定要点：你的话里应当出现「提前写好」「进场前定下」这类字眼，而不是「忍住」「坚持」「心态好」；你应当能说出疼的去向——疼的标价在预算里，不是当场硬扛。</p><p>第二件事，四段操作对号入座。下面四段各对应哪一种陷阱？先落纸写下四个名字与一句识别依据，再展开核对。</p><ul><li>甲：持仓 A 浮盈两成，他一周内分三笔卖光，理由是「到手的利润不能再飞」；持仓 B 浮亏三成，拿了一年半，理由是「卖了才是真亏」。</li><li>乙：老同学在群里喊某只票「人人都在赚」，他看完群消息就挂了单，公司的财报一次没打开过。</li><li>丙：他 15 元买的票跌到 9 元，喊「太便宜了」并加仓；同一天另一只他从没买过的票从 9 元涨向 12 元，他喊「涨这么多，太贵了」。</li><li>丁：账户浮亏 12%，早已越过进场前写好的一成止损线，他连续两周没有执行，理由是「再等等，说不定下周就回来」。</li></ul><details><summary>对号答案</summary><p>甲是处置效应：卖盈持亏的标准形态，决策参照的是浮盈浮亏（成本价），不是持仓质量。乙是从众效应：判定依据全部来自「别人」，基本面环节完全缺席。丙是锚定效应：两句「贵贱」的分母都是他自己的成本或行情的来路，没有一处指向价值。丁最容易被误判成处置效应，但识别点是：去留规则早就写好了（止损线），没能执行的原因是疼——亏损信号触发的威胁反应压过了执行，这是损失厌恶劫持决策的现场。甲与丁的区分方法：甲是按成本价重新决策（规则缺席），丁是写好的规则失灵（执行被疼劫持）。</p></details><p>第三件事，两条流行语，先判后答：</p><blockquote><p>流行语一：「我又不炒股，这四个陷阱跟我无关。」 流行语二：「机构专业，不会得这些毛病。」</p></blockquote><p>各写两三句判定——对、错还是对一半，理由用本章的机理说——写完再展开核对。</p><details><summary>流行语判定</summary><p>流行语一对一半。股票只是陷阱的场地之一：2021 年 1 月抢购的是基金（公开报道口径）；从众与锚定在任何「有别人、有自己历史」的决策场都营业——抢房号、追热点、囤积居奇，用的是同一套机关。流行语二错。对职业投资者持仓的实证研究同样观察到处置效应（行为金融文献口径）；机构的真正优势是把防御工程化——预算、清单、日历。普通投资者抄的正是这份作业，而不是指望智商或头衔免疫。</p></details><p>第四件事，规则可判定性检查。两条防御规则，哪条合格？「跌得太多就先出来，别硬扛」；「丙票收盘价低于 10.90 元的次日开盘，卖出全部持仓」。先用一句话说出前一条哪里不合格，再动手把你自己的一条模糊规则改写成合格版本。</p><details><summary>判定要点</summary><p>前一条不合格：「太多」没有数值，「先出来」没有时点与数量，执行时刻系统一有充分的解释空间——「再多等一天」。合格规则的三要素：触发价（具体数字）、执行时点（次日开盘或当周某日）、动作（卖出多少）。改写时分母规则要过一遍：触发价应当来自进场前算好的止损价（预算反推，第 11 章）或价值侧的失效判定（基本面警报），不能来自成本价——「回到成本我就卖」是锚定，不是防御。</p></details><p>四次检查指向同一条因果链：陷阱在决策触发权上做文章，防御就必须设在触发之前——写死的数字、固定的日期、合法的分母，把扣扳机的那一刻从系统一手里赎回来。</p><h3 id="自查-把四面镜子照进自己的账户" tabindex="-1">自查：把四面镜子照进自己的账户 <a class="header-anchor" href="#自查-把四面镜子照进自己的账户" aria-label="Permalink to &quot;自查：把四面镜子照进自己的账户&quot;">​</a></h3><ol><li>从你自己或身边人的一笔真实交易——申购、买入、卖出都行——指认至少一种陷阱，写出识别依据。判定要点：依据必须落到具体证据上（当时参照了什么数字？跟了谁的动作？是哪条规则没执行？），「当时糊涂了」不算。</li><li>某人必须卖掉浮盈 20% 的 A 与浮亏 18% 的 B 之一。按季度去留日，他动手前该做什么检查？检查结果与「卖哪只」之间是什么关系？</li><li>亲友向你推荐一只「稳赚」基金，你发现身边同事几乎人人都买了。写出动手前该做的两个检查动作，一个对着警报词表，一个对着估值尺（第 7 章）。</li><li>把「亏多了就跑」改写成一条合格规则，写出三要素。再用分母规则检查你写的触发价：它合法吗？</li><li>反事实题：假如一个人完全没有损失厌恶——亏与赢的感受一样重——四种陷阱里哪几条会自然减弱？哪几条照旧有效？他的账户会冒出什么新风险？</li></ol><details><summary>自查答案</summary><ol><li>判定要点：四种陷阱对四种证据——参照了成本价或历史高点（锚定效应）、按浮盈浮亏决定去留（处置效应）、跟了人群的动作（从众效应）；写好的规则没有执行，且原因是不敢面对亏损（损失厌恶）。答出任意一种并给出对应证据即合格。</li><li>检查两只的基本面与估值（第 6 至 8 章的表与尺），分别回答去留问题。结果与「卖哪只」脱钩：可能卖 B 也可能卖 A，只认基本面，不认浮盈浮亏的方向——处置效应的推力到此失效。顺带一提：急用钱本身该由资产配置里预留的现金应对（第 10 章），被迫二选一是配置缺位的信号。</li><li>动作一对警报：同事人人都在买，正踩在警报词表上（身边人晒单成风）——登记，不新增买入。动作二对尺子：查这只基金持仓的估值位置——市盈率与盈利收益率对照无风险利率（第 7 章），再看相对自身历史的高低（第 7 章）。两个动作落纸之后，才轮到决策。</li><li>示例：「丙票收盘价低于 10.90 元的次日开盘，卖出全部持仓」——触发价 10.90、时点次日开盘、动作全部卖出，三要素齐。触发价合法性看来源：来自预算反推的止损价或基本面失效判定，合法；来自「比我成本亏得太多了」，不合法。</li><li>自然减弱的是处置效应（不肯卖亏仓的一半动力没了）与损失厌恶的执行劫持（丁式失灵不会发生）。照旧有效的是锚定效应与从众效应——它们不需要疼参与，只需要参照点错误与跟随动作。新风险：对亏损麻木的人止损迟钝、敢重仓死扛，账户的最大回撤（第 9 章）可能深到回不来——盈亏不对称（第 9 章）不因感受迟钝而豁免，深坑的翻身代价照单全收。</li></ol></details><h2 id="收束-他们不缺聪明-缺一张提前写好的单子" tabindex="-1">收束：他们不缺聪明，缺一张提前写好的单子 <a class="header-anchor" href="#收束-他们不缺聪明-缺一张提前写好的单子" aria-label="Permalink to &quot;收束：他们不缺聪明，缺一张提前写好的单子&quot;">​</a></h2><p>回到 2021 年 1 月那场抢购，三年水下的账现在能逐笔归位了。从众把一群足够聪明的人送进同一个入口；锚定把「净值新高」与「亲戚的收益」当了分母；回调来临时，损失厌恶让多数人不肯认亏离场，处置效应替账户完成最后一次修剪——卖掉还站着的，留下趴下的。判词与智力无关：陷阱劫持的是决策的触发权，不是答题的能力。这场抢购里没有一个人输给市场信息，他们只是把扣扳机的那一刻，借给了跑得最快的系统一。</p><p>本章的存货：损失厌恶、处置效应、锚定效应、从众效应四个名字，各配一条机械防御——无止损不下单、季度去留日、分母规则、拥挤警报加日历再平衡；总纲一句：防御靠规则，不靠意志力。四个词的精确口径进了附录「术语表」，和四条规则放在一起，配着用。</p><p>最容易栽的两个坑，就在这两处。其一，规则写完不执行等于没有：去留日要落在日历上，止损价要落在持仓单上，可判定才有意义。其二，机械不等于免功课：去留日的答案仍要从三张表与估值尺里来（第 6、7 章），规则只接管时机，不豁免研究。</p><p>这些规则也有够不着的地方：规则挡不住系统性下跌。普跌来临时，分散化与资产配置（第 10 章）只能减轻、不能豁免——相关性冲向 +1 的时候，机械防御管的是动作不变形，不是账户不缩水。想把纪律装进更省心的工具，那是指数基金与 ETF（第 13 章）的功课；把「不与陷阱合作」固化成研究流程，每一步配不通过出口，是研究清单（第 14 章）的活。</p><p>本章公开事件均为公开报道口径并标注时间（2021 年 1 月）；老周与全部人物、示意数字为教学合成，与任何真实账户无关；行为金融与神经经济学的表述取文献定性结论。本章不构成任何投资建议。</p>',57)])])}const m=e(r,[["render",t]]);export{u as __pageData,m as default};
